-- =============================================
-- View: VW_HR_EMPLOYEE and AI Metadata Redirection
-- =============================================
IF OBJECT_ID('VW_HR_EMPLOYEE', 'V') IS NOT NULL
    DROP VIEW VW_HR_EMPLOYEE;
GO

CREATE VIEW VW_HR_EMPLOYEE AS
SELECT 
    e.ID,
    e.EMP_CODE,
    e.FIRST_NAME,
    e.LAST_NAME,
    e.STATUS,
    e.IS_ACTIVE,
    o.DEPARTMENT_ID,
    o.DESIGNATION_ID,
    s.DATE_OF_JOINING
FROM HR_EMPLOYEE e
LEFT JOIN HR_EMPLOYEE_ORGANIZATION o ON e.ID = o.EMPLOYEE_ID
LEFT JOIN HR_EMPLOYEE_SCHEDULING s ON e.ID = s.EMPLOYEE_ID;
GO

IF OBJECT_ID('BOS_AI_KNOWLEDGE', 'U') IS NOT NULL
BEGIN
    UPDATE BOS_AI_KNOWLEDGE 
    SET TABLE_NAME = 'VW_HR_EMPLOYEE' 
    WHERE TABLE_NAME = 'HR_EMPLOYEE';
END
GO

IF OBJECT_ID('BOS_AI_COLUMN_METADATA', 'U') IS NOT NULL
BEGIN
    UPDATE BOS_AI_COLUMN_METADATA 
    SET TABLE_NAME = 'VW_HR_EMPLOYEE' 
    WHERE TABLE_NAME = 'HR_EMPLOYEE';
END
GO


